"""${{ values.name }} — generated by the Harborline Python API service template."""

from __future__ import annotations

import os

from fastapi import FastAPI

app = FastAPI(title="${{ values.name }}", docs_url=None, redoc_url=None)


@app.get("/healthz/live", include_in_schema=False)
def live() -> dict[str, str]:
    return {"status": "ok"}


@app.get("/healthz/ready", include_in_schema=False)
def ready() -> dict[str, str]:
    # Add dependency checks (database, broker) here; return 503 when not ready.
    return {"status": "ok"}


@app.get("/api/v1/hello")
def hello(name: str = "world") -> dict[str, str]:
    return {"message": f"Hello, {name[:64]}"}


if os.environ.get("OTEL_SDK_DISABLED", "false").lower() != "true":
    from opentelemetry import metrics, trace
    from opentelemetry.exporter.otlp.proto.grpc.metric_exporter import OTLPMetricExporter
    from opentelemetry.exporter.otlp.proto.grpc.trace_exporter import OTLPSpanExporter
    from opentelemetry.instrumentation.fastapi import FastAPIInstrumentor
    from opentelemetry.sdk.metrics import MeterProvider
    from opentelemetry.sdk.metrics.export import PeriodicExportingMetricReader
    from opentelemetry.sdk.resources import Resource
    from opentelemetry.sdk.trace import TracerProvider
    from opentelemetry.sdk.trace.export import BatchSpanProcessor

    _resource = Resource.create()
    _tp = TracerProvider(resource=_resource)
    _tp.add_span_processor(BatchSpanProcessor(OTLPSpanExporter()))
    trace.set_tracer_provider(_tp)
    metrics.set_meter_provider(
        MeterProvider(resource=_resource, metric_readers=[PeriodicExportingMetricReader(OTLPMetricExporter())])
    )
    FastAPIInstrumentor.instrument_app(app, excluded_urls="healthz/.*")
